// Recebe a resposta do values:batchGet (um único item) e devolve o snapshot.json
// pronto pra ser comitado. Faz também o gate de STATUS GERAL, pra não precisar
// de um nó Code separado só pra isso.
//
// A ordem aqui TEM que bater com a ordem dos `ranges=` na URL do nó
// "Ler planilha (batchGet)": a API do Sheets devolve valueRanges na mesma ordem
// em que foram pedidos.
const ORDEM = ['Checks', 'Dashboard', 'Relogios', 'Lancamentos', 'DRE', 'FluxoCaixa'];
// Largura de cada range, em colunas. O batchGet corta células vazias no fim de
// cada linha, então uma linha que termina em branco volta mais curta que as
// outras — e os filtros por `row.length` descartariam ela por engano.
const LARGURA = { Checks: 7, Dashboard: 8, Relogios: 19, Lancamentos: 23, DRE: 10, FluxoCaixa: 6 };

const resposta = $input.first().json;
const valueRanges = resposta.valueRanges;
if (!Array.isArray(valueRanges) || valueRanges.length !== ORDEM.length) {
  throw new Error(
    'O batchGet devolveu ' + (valueRanges ? valueRanges.length : 0) + ' ranges, ' +
    'esperado ' + ORDEM.length + '. Resposta: ' + JSON.stringify(resposta).slice(0, 500)
  );
}

const abas = {};
ORDEM.forEach((nome, i) => {
  const linhas = valueRanges[i].values || [];
  const w = LARGURA[nome];
  abas[nome] = linhas.map((row) => {
    const out = [];
    for (let c = 0; c < w; c++) out.push((row[c] ?? '').toString().trim());
    return out;
  });
});

function parseBRL(v) {
  if (v === null || v === undefined) return null;
  let s = String(v).trim();
  if (s === '' || s === '-' || s === '—') return null;
  let neg = false;
  if (s.startsWith('(') && s.endsWith(')')) { neg = true; s = s.slice(1, -1); }
  const n = parseFloat(s.replace(/[^\d,.\-]/g, '').replace(/\./g, '').replace(',', '.'));
  if (isNaN(n)) return null;
  return neg ? -n : n;
}
function parsePct(v) {
  if (!v) return 0;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? 0 : n;
}
function parseInt_(v) {
  if (!v) return 0;
  const n = parseInt(String(v).replace(/[^\d\-]/g, ''), 10);
  return isNaN(n) ? 0 : n;
}
function nonblank(row) { return row.filter((c) => c !== ''); }
function dedupe(row) {
  const out = [];
  for (const c of row) if (out.length === 0 || out[out.length - 1] !== c) out.push(c);
  return out;
}

// ---- Gate: Checks / STATUS GERAL ----
let statusGeral = null;
for (const row of abas.Checks) {
  if (row[0] === 'STATUS GERAL') {
    statusGeral = row.find((c, i) => i > 0 && c !== '') ?? '';
    break;
  }
}
if (statusGeral === null) {
  throw new Error('Não achei a linha "STATUS GERAL" na coluna A da aba Checks (range A1:G20).');
}
const pronto = statusGeral === 'OK';

// ---- Dashboard: KPIs + estoque por status ----
const dashRows = abas.Dashboard;
const kv = {};
for (let i = 0; i < dashRows.length - 1; i++) {
  const labels = nonblank(dedupe(dashRows[i]));
  if (!labels.length) continue;
  if (labels.some((c) => /^(R\$|-|\d)/.test(c))) continue;
  const values = nonblank(dedupe(dashRows[i + 1]));
  if (values.length === labels.length && JSON.stringify(values) !== JSON.stringify(labels)) {
    labels.forEach((lab, idx) => { if (!(lab in kv)) kv[lab] = values[idx]; });
  }
}
const kpis = {
  faturamento: parseBRL(kv['FATURAMENTO']),
  lucroLiquido: parseBRL(kv['LUCRO LÍQUIDO']),
  saldoCaixa: parseBRL(kv['SALDO DE CAIXA']) ?? 0,
  capitalEstoque: parseBRL(kv['CAPITAL EM ESTOQUE']) ?? 0,
  pecasEstoque: parseInt_(kv['PEÇAS EM ESTOQUE']),
  margemLiquida: parsePct(kv['MARGEM LÍQUIDA']),
  dividaSocio: parseBRL(kv['DÍVIDA COM SÓCIO']) ?? 0,
  patrimonioBruto: parseBRL(kv['PATRIMÔNIO BRUTO']) ?? 0,
  patrimonioLiquido: parseBRL(kv['PATRIMÔNIO LÍQUIDO']) ?? 0,
};

const estoquePorStatus = [];
for (let i = 0; i < dashRows.length; i++) {
  const nb = nonblank(dashRows[i]);
  if (nb[0] === 'Status' && nb[1] === 'Quantidade') {
    for (let j = i + 1; j < dashRows.length; j++) {
      const nb2 = nonblank(dashRows[j]);
      if (nb2.length < 2) break;
      estoquePorStatus.push({ status: nb2[0], qtd: parseInt_(nb2[1]) });
    }
    break;
  }
}

let mesAnalisado = null;
for (const row of dashRows) {
  const idx = row.indexOf('Mês analisado');
  if (idx !== -1 && row[idx + 1]) { mesAnalisado = row[idx + 1]; break; }
}

// ---- Relógios ----
const watches = abas.Relogios
  .filter((r) => r[0] && r[0].startsWith('TCC'))
  .map((c) => ({
    itemId: c[0], marca: c[1], modelo: c[2], referencia: c[3], condicao: c[4],
    status: c[5], dataCompra: c[6], dataEntrada: c[7], dataVenda: c[8], canal: c[9],
    precoAnuncio: c[10], custoCompleto: c[11], vendaBruta: c[12], deducoes: c[13],
    lucroLiquido: c[14], margem: c[15], dias: c[16] ? parseInt_(c[16]) : null,
    lote: c[17], observacoes: c[18],
  }));

// ---- Lançamentos ----
const LANC = ['id', 'dataCompetencia', 'dataCaixa', 'itemId', 'lote', 'descricao', 'natureza',
  'grupoDre', 'categoria', 'contraparte', 'conta', 'forma', 'moeda', 'valorOriginal', 'cambio',
  'valorBRL', 'status', 'vencimento', 'documento', 'observacoes', 'centroCusto', 'tratamento',
  'precisaoData'];
const lancamentos = abas.Lancamentos
  .filter((r) => r[0] && r[0].startsWith('LCT-'))
  .map((c) => {
    const obj = {};
    LANC.forEach((h, i) => { obj[h] = c[i] ?? ''; });
    return obj;
  });

// ---- DRE mensal ----
const dreIdx = abas.DRE.findIndex((r) => r[0] === 'Mês' && r[1] && r[1].startsWith('Receita'));
const dreMensal = (dreIdx === -1 ? [] : abas.DRE.slice(dreIdx + 1))
  .filter((r) => r[0])
  .map((r) => ({
    mes: r[0],
    receitaBruta: parseBRL(r[1]) ?? 0,
    deducoes: parseBRL(r[2]) ?? 0,
    receitaLiquida: parseBRL(r[3]) ?? 0,
    cmv: parseBRL(r[4]) ?? 0,
    lucroBruto: parseBRL(r[5]) ?? 0,
    despesasOp: parseBRL(r[6]) ?? 0,
    resultadoLiquido: parseBRL(r[7]) ?? 0,
    margemLiquida: parsePct(r[8]),
  }));

// ---- Fluxo de caixa ----
const fxIdx = abas.FluxoCaixa.findIndex((r) => r[0] === 'Mês' && r[1] && r[1].startsWith('Entradas'));
const fluxoCaixa = (fxIdx === -1 ? [] : abas.FluxoCaixa.slice(fxIdx + 1))
  .filter((r) => r[0])
  .map((r) => ({
    mes: r[0],
    entradas: parseBRL(r[1]) ?? 0,
    saidas: parseBRL(r[2]) ?? 0,
    saldoMes: parseBRL(r[3]) ?? 0,
    saldoAcumulado: parseBRL(r[4]) ?? 0,
  }));

// Se o gate passou mas a planilha veio vazia, é sinal de range errado ou aba
// renomeada — melhor estourar aqui do que comitar um snapshot vazio por cima de
// um bom e o painel amanhecer zerado.
if (pronto && watches.length === 0 && lancamentos.length === 0) {
  throw new Error(
    'STATUS GERAL = OK mas não veio nenhum relógio nem lançamento. ' +
    'Confira os ranges Relógios!A5:S505 e Lançamentos!A5:W505 e os nomes das abas.'
  );
}

const snapshot = {
  updatedAt: new Date().toISOString(),
  mesAnalisado,
  kpis,
  estoquePorStatus,
  watches,
  lancamentos,
  dreMensal,
  fluxoCaixa,
};

const texto = JSON.stringify(snapshot, null, 2);

return [{
  json: {
    pronto,
    statusGeral,
    // A API contents do GitHub recebe o conteúdo em base64 — aqui é a API crua,
    // via HTTP Request, então a codificação é nossa mesmo. (O nó nativo do
    // GitHub codifica sozinho; mandar base64 pra ele geraria base64 duplo.)
    contentB64: Buffer.from(texto, 'utf-8').toString('base64'),
    resumo: {
      relogios: watches.length,
      lancamentos: lancamentos.length,
      mesesDre: dreMensal.length,
      mesesFluxo: fluxoCaixa.length,
      bytes: Buffer.byteLength(texto, 'utf-8'),
    },
  },
}];
